fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // According to the problem, list is non-empty and 0 < n < list.len()
    // So we can safely slice without bounds issues.

    let len = list.len();

    // Split into two slices:
    // - from n (inclusive) to end
    // - from 0 (inclusive) to n (exclusive)
    let first_part = &list[n..len];
    let second_part = &list[0..n];

    // Create a new vector with capacity equal to length of original list
    let mut new_list = Vec::with_capacity(len);

    // Extend from first part
    new_list.extend_from_slice(first_part);
    // Extend from second part
    new_list.extend_from_slice(second_part);

    new_list
}